css:
section{position:relative; overflow:hidden}
.deco{position:absolute; z-index:0; pointer-events:none}
.deco--tr{top:-42px; right:-30px; width:min(48vw,420px); color:#dcc9a4}
.deco--l {left:-28px; top:118px; width:118px; transform:rotate(-8deg)}
.deco--ghost{bottom:-60px; left:8%; color:#eee1c1; opacity:.9}  /* 明度差3〜5% */
.arc{position:absolute; top:-260px; left:-220px; width:1100px; height:600px;
  border-radius:50%; border:1.5px dashed #cfc8f5;
  border-color:#cfc8f5 transparent transparent transparent}
